from pathlib import Path
p=Path('personalizza.html')
s=p.read_text()
old='''<style id="hamburgeria-layout-final">body{background-image:linear-gradient(rgba(0,0,0,.10),rgba(0,0,0,.10)),url("${backgroundDataUrl}")!important;background-size:auto 100%!important;background-position:center center!important;background-repeat:no-repeat!important;background-attachment:fixed!important;background-color:#21140d!important}.pagina{background:transparent!important}.logo,.logo-wrap,.logo-box,.logo-container{background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;border:none!important;filter:none!important}.logo{padding:0!important;border-radius:0!important}.logo-wrap:before,.logo-wrap:after,.logo-box:before,.logo-box:after,.logo-container:before,.logo-container:after{display:none!important}@media(min-width:700px){body{background-size:cover!important}}</style>'''
new='''<style id="hamburgeria-layout-reference">html,body{background:#21140d!important}body{background-image:url("${backgroundDataUrl}")!important;background-size:100% 100%!important;background-position:center top!important;background-repeat:no-repeat!important;background-attachment:scroll!important}.pagina{background:transparent!important;padding-top:34px!important}.pagina:before,.pagina:after{display:none!important;content:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;background:none!important}.logo,.logo-wrap,.logo-box,.logo-container{background:transparent!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;border:none!important;filter:none!important}.logo{padding:0!important;border-radius:0!important;max-height:150px!important;width:auto!important;object-fit:contain!important;margin-bottom:76px!important}.logo-wrap:before,.logo-wrap:after,.logo-box:before,.logo-box:after,.logo-container:before,.logo-container:after{display:none!important}h1,.title,.titolo{margin-bottom:18px!important}.message,.testo,.review-message{background:rgba(15,10,7,.58)!important}@media(max-width:640px){body{background-size:100% 100%!important;background-position:center top!important}.pagina{padding-top:30px!important}.logo{max-height:150px!important;margin-bottom:72px!important}}</style>'''
if old not in s: raise SystemExit('hamburgeria final anchor missing')
s=s.replace(old,new,1)
p.write_text(s)
